/// <summary>
/// PricingAttribute of table <c>InventTable</c> field COODualUseCode.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableCOODualUseCode extends UPSPricingAttributeInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, COODualUseCode);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    InventTable inventTable;
    while select COODualUseCode from inventTable
        group by COODualUseCode
    {
        ret.add(inventTable.COODualUseCode);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTable, COODualUseCode));
    qbr.value(queryValue(_value));
}
